action.new:
def _validate_write_key(self, key):
    """Check that an option name is safe for writing.

    Raise InvalidWriteError if the key would produce ambiguous output
    when written to a file.
    """
    if self.SECTCRE.match(key):
        raise InvalidWriteError(key)
    for d in self._delimiters:
        if d in key:
            raise InvalidWriteError(key)

def _write_section(self, fp, section_name, section_items, delimiter):
    """Write a single section to the specified `fp`."""
    fp.write("[{}]\n".format(section_name))
    for key, value in section_items:
        self._validate_write_key(key)
        value = self._interpolation.before_write(self, section_name, key,
                                                 value)

